/// <summary>
/// Runs when process finishes.
/// </summary>
/// <param name = "_dmfDefinitionGroupExecution">DMF group execution definition</param>
public static void postTargetProcess(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
{
    METInventTransferParmLineStaging parmStaging;
    InventTransferParmTable          parmTable;
    InventTransferParmLine           parmLine;
    METInventTransferParmTmp         transferParmTmp,
                                     transferParmTmpCount;
    //Insert in TempTable 1:
    //Inserts all the unique TransferIds and ParmIds in temptable 1 from the staging table.
    insert_recordset transferParmTmp (TransferId, ParmId)
        select TransferId, ParmId from parmStaging
            group by parmStaging.TransferId, parmStaging.ParmId
                where parmStaging.DefinitionGroup   == _dmfDefinitionGroupExecution.DefinitionGroup
                     && parmStaging.ExecutionId     == _dmfDefinitionGroupExecution.ExecutionId
                     && parmStaging.TransferStatus  == DMFTransferStatus::Completed;
    
    //Insert in TempTable 2:
    //Inserts unique TransferIds and ParmIds plus the count of InventTransferParmLine into temptable 2.
    //It calculates count with the help of TransferIds and ParmIds inserted in the temptable 1.
    //We joined InventTransferParmLine with our temptable 1 to filter only for TransferIds and ParmIds found in the staging.
    insert_recordset transferParmTmpCount (TransferId, ParmId, LineCount)
        select TransferId, ParmId, count(RecId) from parmLine
            group by parmLine.TransferId, parmLine.ParmId
                join transferParmTmp
                    where transferParmTmp.TransferId  == parmLine.TransferId
                     &&   transferParmTmp.ParmId      == parmLine.ParmId;
     
    //Updates PurchParmTable:
    //Updates InventTransferParmTable if the TransferId, ParmId and line count in the header is equal to the line count in temptable 2.
    update_recordset parmTable
        setting JobStatus = ParmJobStatus::Waiting
            where parmTable.METIsIntegration == NoYes::Yes
        exists join transferParmTmpCount
            where transferParmTmpCount.TransferId  == parmTable.TransferId
            &&    transferParmTmpCount.ParmId      == parmTable.ParmId
            &&    transferParmTmpCount.LineCount   == parmTable.METIntegrationLineCount;
        
}

    /// <summary>
    /// Maps data source cursor.
    /// </summary>
    /// <param name = "_entityCtx">Data entity runtime context</param>
    /// <param name = "_dataSourceCtx">Data entity data source runtime context</param>
    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        this.skipDataSourceValidateField(fieldNum(METInventTransferParmLineEntity, ParmId), true);
        this.skipDataSourceValidateField(fieldNum(METInventTransferParmLineEntity, TransferId), true);
        this.skipDataSourceValidateField(fieldNum(METInventTransferParmLineEntity, LineNum), true);
        this.skipDataSourceValidateField(fieldNum(METInventTransferParmLineEntity, ItemId), true);

        super(_entityCtx, _dataSourceCtx);

        switch (_entityCtx.getDatabaseOperation())
        {
            case DataEntityDatabaseOperation::Insert:
                switch (_dataSourceCtx.name())
                {
                    case dataEntityDataSourceStr(METInventTransferParmLineEntity, InventTransferParmLine):
                        this.mapInventTransferParmLine(_dataSourceCtx);
                        break;
                }
                break;
        }
    }

    /// <summary>
    /// Maps the data source cursor.
    /// </summary>
    /// <param name = "_dataSourceCtx">Data entity data source runtime context</param>
    protected void mapInventTransferParmLine(DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        InventTransferParmLine transferParmLine = _dataSourceCtx.getBuffer();
        InventTransferLine transferLine = transferParmLine.inventTransferLine();

        transferParmLine.InventDimId = transferLine.InventDimId;

        _dataSourceCtx.setBuffer(transferParmLine);
    }

/// <summary>
/// Validates record.
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();
    ret = ret && this.isItemIdValid();

    return ret;
}

    /// <summary>
    /// Validates item number.
    /// </summary>
    /// <returns>Is valid</returns>
    private boolean isItemIdValid()
    {
        InventTransferLine transferLine = InventTransferLine::findTransIdReceive(this.InventTransId);
        boolean ret = true;

        if (this.ItemId != transferLine.ItemId)
        {
            ret = checkFailed('Item number is not valid.');
        }

        return ret;
    }
